fn xmlRegStateAddTrans(
    mut ctxt: xmlRegParserCtxtPtr,
    mut state: xmlRegStatePtr,
    mut atom: xmlRegAtomPtr,
    mut target: xmlRegStatePtr,
    mut counter: c_int,
    mut count: c_int,
) { unsafe {
    let mut nrtrans: c_int = 0;
    if state.is_null() {
        (*ctxt).error = XML_REGEXP_COMPILE_ERROR as c_int;
        xmlRegexpErrCompile(
            ctxt,
            b"add state: state is NULL\0" as *const u8 as *const c_char,
        );
        return;
    }
    if target.is_null() {
        (*ctxt).error = XML_REGEXP_COMPILE_ERROR as c_int;
        xmlRegexpErrCompile(
            ctxt,
            b"add state: target is NULL\0" as *const u8 as *const c_char,
        );
        return;
    }
    nrtrans = (*state).nbTrans - 1 as c_int;
    while nrtrans >= 0 as c_int {
        let mut trans: xmlRegTransPtr = (*state).trans.offset(nrtrans as isize) as xmlRegTransPtr;
        if (*trans).atom == atom
            && (*trans).to == (*target).no
            && (*trans).counter == counter
            && (*trans).count == count
        {
            return;
        }
        nrtrans -= 1;
    }
    if (*state).maxTrans == 0 as c_int {
        (*state).maxTrans = 8 as c_int;
        (*state).trans = xmlMalloc.expect("non-null function pointer")(
            ((*state).maxTrans as size_t)
                .wrapping_mul(::core::mem::size_of::<xmlRegTrans>() as size_t),
        ) as *mut xmlRegTrans;
        if (*state).trans.is_null() {
            xmlRegexpErrMemory(
                ctxt,
                b"adding transition\0" as *const u8 as *const c_char,
            );
            (*state).maxTrans = 0 as c_int;
            return;
        }
    } else if (*state).nbTrans >= (*state).maxTrans {
        let mut tmp: *mut xmlRegTrans = ::core::ptr::null_mut::<xmlRegTrans>();
        (*state).maxTrans *= 2 as c_int;
        tmp = xmlRealloc.expect("non-null function pointer")(
            (*state).trans as *mut c_void,
            ((*state).maxTrans as size_t)
                .wrapping_mul(::core::mem::size_of::<xmlRegTrans>() as size_t),
        ) as *mut xmlRegTrans;
        if tmp.is_null() {
            xmlRegexpErrMemory(
                ctxt,
                b"adding transition\0" as *const u8 as *const c_char,
            );
            (*state).maxTrans /= 2 as c_int;
            return;
        }
        (*state).trans = tmp;
    }
    let ref mut fresh7 = (*(*state).trans.offset((*state).nbTrans as isize)).atom;
    *fresh7 = atom;
    (*(*state).trans.offset((*state).nbTrans as isize)).to = (*target).no;
    (*(*state).trans.offset((*state).nbTrans as isize)).counter = counter;
    (*(*state).trans.offset((*state).nbTrans as isize)).count = count;
    (*(*state).trans.offset((*state).nbTrans as isize)).nd = 0 as c_int;
    (*state).nbTrans += 1;
    xmlRegStateAddTransTo(ctxt, target, (*state).no);
} }
